js:
Pagina.pronta(function () {
    $(window).scroll(function () {
        // Posição do scroll em relação ao topo da página
        var scrollTop = $(window).scrollTop();

          // Verifica se o topo do banner saiu da tela
        if (scrollTop > 0) {
            $('.estiloFixo').removeClass('ctaHide'); 
        } else {            
        	  $('.estiloFixo').addClass('ctaHide'); 
				}



		// Controle adicional com o rodapé
        var scrollBottom = $(document).height() - $(window).height() - $(window).scrollTop() - $('footer').height();
        if (scrollBottom < 1) {
            $('.estiloFixo').addClass('btnCTARelativo');
        } else {
            $('.estiloFixo').removeClass('btnCTARelativo');
        }

		});

    // Dispara o evento de scroll quando a página carregar para garantir o comportamento correto
    $(window).trigger('scroll');
});;

