$(document).ready(function () {
    // Máscaras para os campos de telefone
    $(".academic-form-wrapper #telefoneCel").mask("(00) 00000-0000");
    $(".academic-form-wrapper #telefonefixo").mask("(00) 0000-0000");

    // Evento de clique no botão enviar
    $(".academic-form-wrapper .enviarBtn #submitBtn").click(function () {
        if (validateFields()) {
            enviarParaListaDinamica();
        }
    });
});

function validateFields() {
    var isValid = true;

    // Validação dos campos obrigatórios
    isValid &= validateField(".academic-form-wrapper #nomeCompleto");
    isValid &= validateField(".academic-form-wrapper #telefoneCel");
    isValid &= validateField(".academic-form-wrapper #telefonefixo");
    isValid &= validateField(".academic-form-wrapper #crm");
    isValid &= validateField(".academic-form-wrapper #especializacao");
    isValid &= validateField(".academic-form-wrapper #cursos");

    // Validação do reCAPTCHA
    isValid &= validateRecaptcha();

    if (!isValid) {
        scrollIntoViewAdjusted($('.academic-form-wrapper .error-message')[0], 200);
    }

    return isValid;
}

function validateField(selector) {
    removeError(selector);

    if ($(selector).val() == undefined || $(selector).val().trim() === "") {
        $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    return true;
}

function validateRecaptcha() {
    // Remove erro anterior do reCAPTCHA
    $('.academic-form-wrapper .recaptcha-container .error-message').remove();

    // Verifica se o reCAPTCHA foi preenchido
    var recaptchaResponse = grecaptcha.getResponse();

    if (!recaptchaResponse || recaptchaResponse.length === 0) {
        $("<p class='error-message'>*Por favor, confirme que você não é um robô</p>")
            .appendTo('.academic-form-wrapper .recaptcha-container');

        // Adiciona borda vermelha ao container do reCAPTCHA
        $('.academic-form-wrapper .g-recaptcha').addClass("error-border");

        return false;
    }

    return true;
}

function removeError(selector) {
    $(selector).nextAll(".error-message").remove();
    $(selector).removeClass("error-border");
}

function scrollIntoViewAdjusted(elem, offset = 0) {
    try {
        if (elem) {
            window.scrollBy({
                top: elem.getBoundingClientRect().top - offset,
                behavior: "smooth"
            });
        }
    } catch (error) {
        console.error("Erro ao dar scroll até o campo inválido:", error);
    }
}

function enviarParaListaDinamica() {
    // Desabilita o botão para evitar duplo clique
    $(".academic-form-wrapper #submitBtn").prop('disabled', true).text('Enviando...');

    // Mostra loading
    $(".academic-form-wrapper #loadingDiv").show();

    const data = {
        tabelaDinamica: "Academic", // nome da tabela
        groupId: window.__SITE__.codigo, // ID do site
        companyId: '', // ID da empresa
        userId: '', // ID do usuário logado
        nomeCompleto: $(".academic-form-wrapper #nomeCompleto").val(),
        telefoneCelular: $(".academic-form-wrapper #telefoneCel").val(),
        telefoneFixo: $(".academic-form-wrapper #telefonefixo").val(),
        crm: $(".academic-form-wrapper #crm").val(),
        especializacaoPretendida: $(".academic-form-wrapper #especializacao").val(),
        cursosDeInteresse: $(".academic-form-wrapper #cursos").val(),
        recaptchaResponse: grecaptcha.getResponse() // Inclui resposta do reCAPTCHA
    };

    // URL da API para envio dos dados da Lista Dinâmica (DDL)
    const apiURL = window.location.origin + "/api/servicos/listaDinamica/gravar-lista-dinamica";

    $.ajax({
        url: apiURL,
        method: "POST",
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + ''
        },
        data: JSON.stringify(data),
        success: function (res, textStatus, jqXHR) {
            // Esconde loading
            $(".academic-form-wrapper #loadingDiv").hide();

            if (jqXHR.status === 200) {
                // Mostra mensagem de sucesso
                showSuccessMessage();
            } else {
                showErrorMessage("Erro ao salvar os dados.");
                resetSubmitButton();
            }
        },
        error: function (err) {
            console.error("Erro na requisição:", err);

            // Esconde loading
            $(".academic-form-wrapper #loadingDiv").hide();

            // Mostra mensagem de erro específica baseada no status
            var errorMessage = "Erro técnico ao salvar os dados.";

            if (err.status === 400) {
                errorMessage = "Dados inválidos. Verifique os campos preenchidos.";
            } else if (err.status === 401) {
                errorMessage = "Sessão expirada. Recarregue a página e tente novamente.";
            } else if (err.status === 500) {
                errorMessage = "Erro interno do servidor. Tente novamente em alguns minutos.";
            }

            showErrorMessage(errorMessage);
            resetSubmitButton();
        }
    });
}

function showSuccessMessage() {
    // Esconde o formulário
    $(".academic-form-wrapper #formDuvida").hide();

    // Mostra mensagem de sucesso
    $(".academic-form-wrapper #msgSucesso").show();

    // Limpa o formulário
    $(".academic-form-wrapper #formDuvida input").each(function() {
        $(this).val('');
    });

    // Remove bordas de erro do reCAPTCHA
    $('.academic-form-wrapper .g-recaptcha').removeClass("error-border");
    $('.academic-form-wrapper .recaptcha-container .error-message').remove();

    // Reset do reCAPTCHA
    grecaptcha.reset();

    // Scroll para o topo da mensagem de sucesso
    scrollIntoViewAdjusted($('.academic-form-wrapper #msgSucesso')[0], 100);
}

function showErrorMessage(message) {
    alert(message);
}

function resetSubmitButton() {
    $(".academic-form-wrapper #submitBtn").prop('disabled', false).text('Enviar');
};

