$(document).ready(function () {
  // Máscaras para os campos de telefone
  $(".prevrio-form-wrapper #telefoneCel").mask("(00) 00000-0000");
  $(".prevrio-form-wrapper #telefonefixo").mask("(00) 0000-0000");

  // Evento de clique no botão enviar
  $(".prevrio-form-wrapper .enviarBtn #submitBtn").click(function () {
    if (validateFields()) {
      enviarParaListaDinamica();
    }
  });
});

function validateFields() {
  var isValid = true;

  // Validação dos campos obrigatórios
  isValid &= validateField(".prevrio-form-wrapper #nomeCompleto");
  isValid &= validateField(".prevrio-form-wrapper #telefoneCel");
  isValid &= validateField(".prevrio-form-wrapper #telefonefixo");
  isValid &= validateField(".prevrio-form-wrapper #email");
  isValid &= validateField(".prevrio-form-wrapper #duvida");

  // Validação específica do e-mail
  isValid &= validateEmail(".prevrio-form-wrapper #email");

  // Validação do reCAPTCHA
  isValid &= validateRecaptcha();

  if (!isValid) {
    scrollIntoViewAdjusted($(".prevrio-form-wrapper .error-message")[0], 200);
  }

  return isValid;
}

function validateField(selector) {
  removeError(selector);

  if ($(selector).val() == undefined || $(selector).val().trim() === "") {
    $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
    $(selector).addClass("error-border").focus();
    return false;
  }

  return true;
}

function validateEmail(selector) {
  // Se o campo estiver vazio, a validação de campo obrigatório já tratou
  if ($(selector).val().trim() === "") {
    return true;
  }

  removeError(selector);

  // Regex para validação de e-mail
  var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailRegex.test($(selector).val().trim())) {
    $("<p class='error-message'>*Digite um e-mail válido</p>").insertAfter(
      selector
    );
    $(selector).addClass("error-border").focus();
    return false;
  }

  return true;
}

function validateRecaptcha() {
  // Remove erro anterior do reCAPTCHA
  $(".prevrio-form-wrapper .recaptcha-container .error-message").remove();

  // Verifica se o reCAPTCHA foi preenchido
  var recaptchaResponse = grecaptcha.getResponse();

  if (!recaptchaResponse || recaptchaResponse.length === 0) {
    $(
      "<p class='error-message'>*Por favor, confirme que você não é um robô</p>"
    ).appendTo(".prevrio-form-wrapper .recaptcha-container");
    return false;
  }

  return true;
}

function removeError(selector) {
  $(selector).nextAll(".error-message").remove();
  $(selector).removeClass("error-border");
}

function scrollIntoViewAdjusted(elem, offset = 0) {
  try {
    if (elem) {
      window.scrollBy({
        top: elem.getBoundingClientRect().top - offset,
        behavior: "smooth",
      });
    }
  } catch (error) {
    console.error("Erro ao dar scroll até o campo inválido:", error);
  }
}

function enviarParaListaDinamica() {
  // Desabilita o botão para evitar duplo clique
  $(".prevrio-form-wrapper #submitBtn")
    .prop("disabled", true)
    .text("Enviando...");

  // Mostra loading
  $(".prevrio-form-wrapper #loadingDiv").show();

  let subject = "Prev-Rio: Dúvidas sobre os planos";
  const form = document.getElementById("formDuvida");
  const filledFormData = new FormData(form);

  const template = `
            <body>
                <div>
                    <p><strong>Prezado (a): Responsável NDI</strong></p>
                    <p>Segue a solicitação para ser um Corretor conforme informações abaixo:</p>
                        ${[...filledFormData]
                          .map(([key, value]) => {
                            const inputElement = form.querySelector(
                              `[name="${key}"]`
                            );
                            const labelElement = form.querySelector(
                              `label[for="${inputElement.id}"]`
                            );
                            const labelText = labelElement
                              ? labelElement.textContent
                              : null;

                            const displayValue =
                              inputElement.tagName === "SELECT"
                                ? inputElement.selectedOptions[0]?.text
                                : value;

                            return displayValue !== "" && labelText != null
                              ? `<p>${labelText}: ${displayValue}</p>`
                              : "";
                          })
                          .join("")}
                    <p>Atenciosamente,</p>
                    <p>${$(".prevrio-form-wrapper #nomeCompleto").val()}</p>
                    <p>${$(".prevrio-form-wrapper #telefoneCel").val()}</p>
				    <p>URL Página: ${window.location.href}</p>
                </div>
            </body>
        `;

  const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

  const data = {
    tabelaDinamica: "Prevrio", // nome da tabela
    internalEmail: configuration.emailInterno,
    subject: subject,
    groupId: window.__SITE__.codigo, // ID do site
    companyId: '', // ID da empresa
    userId: '', // ID do usuário logado
    nomeCompleto: $(".prevrio-form-wrapper #nomeCompleto").val(),
    telefoneCelular: $(".prevrio-form-wrapper #telefoneCel").val(),
    telefoneFixo: $(".prevrio-form-wrapper #telefonefixo").val(),
    email: $(".prevrio-form-wrapper #email").val(),
    duvida: $(".prevrio-form-wrapper #duvida").val(),
    template: cleanTemplate
  };

  // URL da API para envio dos dados
  const apiURL =
    window.location.origin + "/api/servicos/generico/salvar-lista-enviar-email";

  $.ajax({
    url: apiURL,
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      Authorization: "Bearer " + '',
    },
    data: JSON.stringify(data),
    success: function (res, textStatus, jqXHR) {
      // Esconde loading
      $(".prevrio-form-wrapper #loadingDiv").hide();

      if (jqXHR.status === 200) {
        // Mostra mensagem de sucesso
        showSuccessMessage();
      } else {
        showErrorMessage("Erro ao salvar os dados.");
        resetSubmitButton();
      }
    },
    error: function (err) {
      console.error("Erro na requisição:", err);

      // Esconde loading
      $(".prevrio-form-wrapper #loadingDiv").hide();

      // Mostra mensagem de erro específica baseada no status
      var errorMessage = "Erro técnico ao salvar os dados.";

      if (err.status === 400) {
        errorMessage = "Dados inválidos. Verifique os campos preenchidos.";
      } else if (err.status === 401) {
        errorMessage =
          "Sessão expirada. Recarregue a página e tente novamente.";
      } else if (err.status === 500) {
        errorMessage =
          "Erro interno do servidor. Tente novamente em alguns minutos.";
      }

      showErrorMessage(errorMessage);
      resetSubmitButton();
    },
  });
}

function showSuccessMessage() {
  // Esconde o formulário
  $(".prevrio-form-wrapper #formDuvida").hide();

  // Mostra mensagem de sucesso
  $(".prevrio-form-wrapper #msgSucesso").show();

  // Limpa o formulário
  $(
    ".prevrio-form-wrapper #formDuvida input, .prevrio-form-wrapper #formDuvida textarea"
  ).each(function () {
    $(this).val("");
  });

  // Reset do reCAPTCHA
  grecaptcha.reset();

  // Scroll para o topo da mensagem de sucesso
  scrollIntoViewAdjusted($(".prevrio-form-wrapper #msgSucesso")[0], 100);
}

function showErrorMessage(message) {
  alert(message);
}

function resetSubmitButton() {
  $(".prevrio-form-wrapper #submitBtn").prop("disabled", false).text("Enviar");
};

