const faqContainer = fragmentElement.querySelector('.sv-faq');

if (faqContainer) {
  const buttons = faqContainer.querySelectorAll('[data-toggle="collapse"]');

  buttons.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetSelector = btn.getAttribute('data-target');
      const target = document.querySelector(targetSelector);
      const icon = btn.querySelector('.plus-icon');

      // Toggle da classe show
      const isOpening = !target.classList.contains('show');
      target.classList.toggle('show');

      // Atualiza aria-expanded
      btn.setAttribute('aria-expanded', isOpening ? 'true' : 'false');

      // Ícones originais
      const iconPlus = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABgAAAAYCAYAAADgdz34AAAABHNCSVQICAgIfAhkiAAAAHVJREFUSEtjZCASsJiu+Q9X+v+/458zoQeI0cpIjCKQmlELCIbUaBCNBhHOEGBESR0EA4pEBcAcPxwsMFntQJTHGRn3w9Qx/mcs/M/w7wIhfX/+sFwYLewIhRLDaBCNBhEiBGhfoyHleFAOZbgQ+IFgBAAVAAAtQqBxoYU6fwAAAABJRU5ErkJggg==";
      const iconMinus = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABgAAAAECAYAAACUY/8YAAAABHNCSVQICAgIfAhkiAAAACRJREFUGFdjZDFd85+BRuA/4/8wxqFvAbPZ6lAahRAD4///nwE+OhDbCq6jOAAAAABJRU5ErkJggg==";

      // Alterna bordas
      btn.classList.toggle('border-bottom', !isOpening);
      btn.classList.toggle('border-bottom-0', isOpening);

      // Alterna ícone
      icon.setAttribute('src', isOpening ? iconMinus : iconPlus);
    });
  });
}
