const fragmentContainer = fragmentElement.querySelector('.global-landing-page-form');
const submitBtn = fragmentContainer.querySelector('.submit-btn');

const RECAPTCHA_ENABLED = true;

function showErrorMessage(message) {
    alert(message);
}

function escapeHtml(valor) {
    return String(valor || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function scrollToElementWithOffset(element, offsetTop) {
    if (!element) return;
    const rect = element.getBoundingClientRect();
    const top = rect.top + window.pageYOffset - (offsetTop || 0);
    window.scrollTo({ top, behavior: 'smooth' });
}

function showSuccessMessage() {
    const formTitle = fragmentContainer.querySelector(".form-title");
    const formDescription = fragmentContainer.querySelector(".form-description");
    const scrollOffsetTop = 200;

    if (typeof window.jQuery !== 'undefined') {
        window.jQuery(fragmentContainer).find("#formCancer").hide();
        const $msg = window.jQuery(fragmentContainer).find("#msgSucesso");
        $msg.css('display', 'flex').hide().fadeIn(function () {
            scrollToElementWithOffset(this, scrollOffsetTop);
        });
    } else {
        const form = fragmentContainer.querySelector('#formCancer');
        const msgSucesso = fragmentContainer.querySelector('#msgSucesso');
        if (form) form.style.display = 'none';
        if (msgSucesso) {
            msgSucesso.style.display = 'flex';
            scrollToElementWithOffset(msgSucesso, scrollOffsetTop);
        }
    }

    if (formTitle) formTitle.style.display = 'none';
    if (formDescription) formDescription.style.display = 'none';
}

function resetSubmitButton() {
    submitBtn.disabled = false;
    submitBtn.textContent = 'Enviar';
    resetRecaptcha();
}

function showLoading() {
    if (typeof window.jQuery !== 'undefined') {
        window.jQuery("#loadingDiv").show();
        return;
    }

    const loadingDiv = document.getElementById('loadingDiv');
    if (loadingDiv) loadingDiv.style.display = 'block';
}

function hideLoading() {
    if (typeof window.jQuery !== 'undefined') {
        window.jQuery("#loadingDiv").hide();
        return;
    }

    const loadingDiv = document.getElementById('loadingDiv');
    if (loadingDiv) loadingDiv.style.display = 'none';
}

function isRecaptchaChecked() {
    if (typeof grecaptcha === 'undefined' || typeof grecaptcha.getResponse !== 'function') {
        return false;
    }
    try {
        return (grecaptcha.getResponse() || '').length > 0;
    } catch (e) {
        // widget ainda não renderizado
        return false;
    }
}

function resetRecaptcha() {
    if (!RECAPTCHA_ENABLED) return;
    if (typeof grecaptcha !== 'undefined' && typeof grecaptcha.reset === 'function') {
        try {
            grecaptcha.reset();
        } catch (e) {
            // widget ainda não renderizado
        }
    }
}

function checkRecaptcha() {
    // O botão fica ativo; o reCAPTCHA é conferido no clique em "Enviar".
    submitBtn.disabled = false;
}

function FormValidator() {
    this.formData = {};
    this.collectFormData = function(form) {
        const formElement = fragmentContainer.querySelector("#" + form);
        if (!formElement) return {};

        const formData = {};
        const fields = formElement.querySelectorAll('input, select, textarea');

        fields.forEach(field => {
                formData[field.name || field.id] = field.value.trim();
        });

        this.formData = formData;
        return formData;
    };

    this.validatePhone = function(field) {
        const value = field.value.trim();
        const formGroup = field.closest('.form-container-group');

        const existingMsg = formGroup?.querySelector('.error-message');
        if (existingMsg) existingMsg.remove();

        const cleaned = value.replace(/\D/g, '');

        if (/\p{L}/u.test(value)) {
            const msg = document.createElement('div');
            msg.className = 'error-message oxygen-p3-regular';
            msg.textContent = 'Número inválido';
            formGroup.appendChild(msg);
            return false;
        }

        if ((cleaned.length > 0 && cleaned.length < 10) || cleaned.length > 11) {
            const msg = document.createElement('div');
            msg.className = 'error-message oxygen-p3-regular';
            msg.textContent = 'Número inválido';
            formGroup.appendChild(msg);
            return false;
        }

        return cleaned.length === 10 || cleaned.length === 11;
    };

    this.validateName = function(name) {
        return name.trim().length >= 8;
    };

    this.validateIdade = function(field) {
        const value = field.value.trim();
        const formGroup = field.closest('.form-container-group');

        const existingMsg = formGroup?.querySelector('.error-message');
        if (existingMsg) existingMsg.remove();

        if (!/^\d+$/.test(value)) {
            const msg = document.createElement('div');
            msg.className = 'error-message oxygen-p3-regular';
            msg.textContent = 'Apenas números';
            formGroup.appendChild(msg);
            return false;
        }

        const cleaned = value.replace(/\D/g, '');
        return cleaned.length > 0 && cleaned.length <= 3 && parseInt(cleaned) > 0;
    };

    this.validateCarteirinha = function(field) {
        const value = field.value.trim();
        const formGroup = field.closest('.form-container-group');

        const existingMsg = formGroup?.querySelector('.error-message');
        if (existingMsg) existingMsg.remove();

        if (!/^\d+$/.test(value)) {
            const msg = document.createElement('div');
            msg.className = 'error-message oxygen-p3-regular';
            msg.textContent = 'Apenas números';
            formGroup.appendChild(msg);
            return false;
        }

        if (value.length < 14) {
            const msg = document.createElement('div');
            msg.className = 'error-message oxygen-p3-regular';
            msg.textContent = 'Mínimo de 14 caracteres';
            formGroup.appendChild(msg);
            return false;
        }

        return true;
    };


    this.addErrorToGroup = function(field) {
        const formGroup = field.closest('.form-container-group');
        if (formGroup) {
            formGroup.classList.add('field-error');

            const label = formGroup.querySelector('label');
            if (label && !label.textContent.includes('(Campo Obrigatório)') && field.hasAttribute('required') && !field.value.trim()) {
                label.textContent = label.textContent.trim() + ' (Campo Obrigatório)';
            }
        }
    };

   this.removeErrorFromGroup = function(field) {
        const formGroup = field.closest('.form-container-group');
        if (formGroup) {
            formGroup.classList.remove('field-error');

            const label = formGroup.querySelector('label');
            if (label && label.textContent.includes('(Campo Obrigatório)')) {
                label.textContent = label.textContent.replace(/\s*\(Campo Obrigatório\)/, '');
            }
        }
    };

    this.validateField = function(field) {
        // required
        if (field.hasAttribute('required') && !field.value.trim()) {
            this.addErrorToGroup(field);
            return false;
        }

        // nome
        if ((field.id === 'nome' || field.id === 'nomeFantasia') && field.value.trim()) {
            if (!this.validateName(field.value)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        // telefone
        if ((field.id === 'telefone') && field.value.trim()) {
            if (!this.validatePhone(field)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

       // idade
        if (field.id === 'idade' && field.value.trim()) {
            if (!this.validateIdade(field)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        // carteirinha
        if (field.id === 'carteirinha' && field.value.trim()) {
            if (!this.validateCarteirinha(field)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        this.removeErrorFromGroup(field);
        return true;
    };

    this.applyPhoneMask = function(input) {
        let value = input.value.replace(/\D/g, '');
        if (value.length > 11) {
            value = value.slice(0, 11);
        }

        if (value.length <= 10) {
            // fixo: (00) 0000-0000
            value = value.replace(/(\d{2})(\d{4})(\d{4})/, '($1) $2-$3');
        } else {
            // celular: (00) 00000-0000
            value = value.replace(/(\d{2})(\d{5})(\d{4})/, '($1) $2-$3');
        }

        input.value = value;
    };

    this.setupFieldEvents = function(field) {
        const validator = this;

        if (field.id === 'telefone') {
            field.addEventListener('input', function() {
                validator.applyPhoneMask(this);
                if (this.value.trim()) {
                    validator.removeErrorFromGroup(this);
                }
            });

            if (field.value.trim()) {
                validator.applyPhoneMask(field);
            }
        }


        if (field.id === 'nome' || field.id === 'nomeFantasia') {
            field.addEventListener('blur', function() {
                validator.validateField(this);
            });

            field.addEventListener('input', function() {
                if (this.value.trim()) {
                    validator.removeErrorFromGroup(this);
                }
            });
        }

        field.addEventListener('blur', function() {
            validator.validateField(this);
        });

        field.addEventListener('input', function() {
            if (this.value.trim()) {
                validator.removeErrorFromGroup(this);
            }
        });
    };

    this.validateForm = function(form) {
        const validator = this;
        const formElement = fragmentContainer.querySelector("#"+ form);
        if (!formElement) return;

        // Field Events
        const phoneFields = formElement.querySelectorAll('#telefone');
        const nameFields = formElement.querySelectorAll('#nome, #nomeFantasia');
        const requiredFields = formElement.querySelectorAll('[required]');

        // Aplicar eventos para todos os campos com máscara
        phoneFields.forEach(field => {
            validator.setupFieldEvents(field);
        });

        nameFields.forEach(field => {
            validator.setupFieldEvents(field);
        });

        requiredFields.forEach(field => {
            validator.setupFieldEvents(field);
        });

        // Evento de Submissão
        formElement.addEventListener('submit', function(e) {
            e.preventDefault();

            let isValid = true;

            // Remover todos os erros existentes
            const allFields = formElement.querySelectorAll('input, select, textarea');
            allFields.forEach(field => {
                validator.removeErrorFromGroup(field);
            });

            requiredFields.forEach(field => {
                if (!validator.validateField(field)) {
                    isValid = false;
                }
            });

            phoneFields.forEach(field => {
                if (field.value.trim() && !validator.validateField(field)) {
                    isValid = false;
                }
            });

            nameFields.forEach(field => {
                if (field.value.trim() && !validator.validateField(field)) {
                    isValid = false;
                }
            });

            if (!isValid) {
                // Scroll para o primeiro campo com erro
                const firstError = formElement.querySelector('.field-error');
                if (firstError) {
                    firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    const input = firstError.querySelector('input, select, textarea');
                    if (input) input.focus();
                }
                return;
            }

            // reCAPTCHA obrigatório antes do envio
            if (RECAPTCHA_ENABLED && !isRecaptchaChecked()) {
                showErrorMessage('Por favor, confirme que você não é um robô.');
                return;
            }

            const formData = validator.collectFormData(form);

            formValidator.sendFormData(formElement, formData);
        });
    };

    this.sendFormData = function(formElement, formData) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Enviando...';
        showLoading();

        const isMama = configuration.formModel == "lpMama";
        const subject = isMama ? "Cadastro LP Mama" : "Cadastro LP Chron";

        const estadoSelect = formElement.querySelector('#estado');
        const estadoLabel = estadoSelect?.options?.[estadoSelect.selectedIndex]?.text || (formData.estado || '');

        const template = `
            <body>
                <div>
                    <p>Segue novo cadastro através da LP:</p>
                    <p><strong>DADOS DO PACIENTE</strong></p>
                    <div><strong>Nome:</strong> ${escapeHtml(formData.nome)}</div>
                    <div><strong>Número da Carteirinha:</strong> ${escapeHtml(formData.carteirinha)}</div>
                    <div><strong>Telefone:</strong> ${escapeHtml(formData.telefone)}</div>
                    <div><strong>Idade:</strong> ${escapeHtml(formData.idade)}</div>
                    <div><strong>Estado:</strong> ${escapeHtml(estadoLabel)}</div>
                    <div><strong>Cidade:</strong> ${escapeHtml(formData.cidade)}</div>
                    ${isMama ? `
                        <p><strong>QUESTIONÁRIO</strong></p>
                        <div><strong>Você tem câncer de mama?:</strong> ${escapeHtml(formData.temCancerdeMama)}</div>
                        <div><strong>O câncer é localizado?:</strong> ${escapeHtml(formData.cancerLocalizado)}</div>
                        <div><strong>O câncer é metastático?:</strong> ${escapeHtml(formData.cancerMetastatico)}</div>
                        <div><strong>Está tomando comprimidos de hormônio há &gt;3 e 5 anos?:</strong> ${escapeHtml(formData.tomandoComprimidoHormonio)}</div>
                    ` : ''}
                </div>

            </body>
        `;

        const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

        // Payload idêntico ao de homologação (sem recaptchaToken)
        const data = {
            to: formData.emailTo || configuration.emailTo || '',
            subject: subject,
            body: cleanTemplate
        };

        const apiURL = window.location.origin.toString() + "/api/servicos/email/enviar";

        if (typeof window.jQuery !== 'undefined' && typeof window.jQuery.ajax === 'function') {
            window.jQuery.ajax({
                url: apiURL,
                method: "POST",
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json'
                },
                data: JSON.stringify(data),
                success: function (res, textStatus, jqXHR) {
                    hideLoading();
                    if (jqXHR.status === 200) {
                        showSuccessMessage();
                    } else {
                        showErrorMessage("Erro ao enviar os dados.");
                        resetSubmitButton();
                    }
                },
                error: function (err) {
                    console.error("Erro na requisição:", err);
                    hideLoading();

                    var errorMessage = "Erro técnico ao enviar os dados.";
                    if (err.status === 400) errorMessage = "Dados inválidos. Verifique os campos preenchidos.";
                    else if (err.status === 401) errorMessage = "Sessão expirada. Recarregue a página e tente novamente.";
                    else if (err.status === 500) errorMessage = "Erro interno do servidor. Tente novamente em alguns minutos.";

                    showErrorMessage(errorMessage);
                    resetSubmitButton();
                }
            });
        } else {
            fetch(apiURL, {
                method: 'POST',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(data)
            })
            .then(response => {
                hideLoading();
                if (response && response.status === 200) {
                    showSuccessMessage();
                } else {
                    showErrorMessage("Erro ao enviar os dados.");
                    resetSubmitButton();
                }
            })
            .catch(error => {
                console.error("Erro na requisição:", error);
                hideLoading();
                showErrorMessage("Erro técnico ao enviar os dados.");
                resetSubmitButton();
            });
        }
    };

    this.handleFormResponse = function handleFormResponse(response) {
        if (response && response.status === 200) {
            showSuccessMessage();
            return true;
        }
        return false;
    }

}

const formValidator = new FormValidator();
checkRecaptcha();

formValidator.validateForm('formCancer');;

