js:
(function () {
    const steps = document.querySelectorAll('.wizard-step');
    let currentStep = 0;
    const form = document.getElementById('formProstata');
    const inputData = document.getElementById('dataNascimento');
    const inputCarteirinha = document.getElementById('carteirinha');

    function ValidatorForm() {
        this.maskDate = function(value) {
            return value
                .replace(/\D/g, "")
                .replace(/(\d{2})(\d)/, "$1/$2")
                .replace(/(\d{2})(\d)/, "$1/$2")
                .replace(/(\d{4})(\d+?)$/, "$1");
        };

        this.validateRequired = function(field) {
            const value = field.value.trim();
            const group = field.closest('.form-group') || field.closest('.form-container-group') || field.parentElement;
            this.removeError(group);
            if (!value) {
                this.showError(group, 'Este campo é obrigatório');
                return false;
            }
            return true;
        };

        this.validateCarteirinha = function(field) {
            const value = field.value.trim();
            const group = field.closest('.form-group') || field.parentElement;
            this.removeError(group);

            if (!value) {
                this.showError(group, 'Este campo é obrigatório');
                return false;
            }

            const regexAlfanumerica = /^[a-zA-Z0-9]{14,}$/;
            if (value.length < 14) {
                this.showError(group, 'Mínimo de 14 caracteres');
                return false;
            }
            if (!regexAlfanumerica.test(value)) {
                this.showError(group, 'Apenas letras e números');
                return false;
            }
            return true;
        };

        this.validateRecaptcha = function(currentStepEl) {
            const recaptchaContainer = currentStepEl.querySelector('.form-cancerProstata-recaptcha');
            if (!recaptchaContainer) return true;

            const response = (typeof grecaptcha !== 'undefined') ? grecaptcha.getResponse() : "bypass";

            if (response.length === 0) {
                const group = recaptchaContainer;
                this.showError(group, 'Por favor, confirme que você não é um robô');
                return false;
            }
            this.removeError(recaptchaContainer);
            return true;
        };

        this.validateRadio = function(name, currentStepEl) {
            const radios = currentStepEl.querySelectorAll(`input[name="${name}"]`);
            if (radios.length === 0) return true;

            const firstRadio = radios[0];
            const group = firstRadio.closest('.question') || firstRadio.closest('.form-group');

            const containerPai = firstRadio.closest('.medicamentos');
            if (containerPai && !containerPai.classList.contains('show-container')) {
                return true; 
            }

            let checked = Array.from(radios).some(r => r.checked);
            if (!checked) {
                this.showError(group, 'Selecione uma opção');
                return false;
            }
            this.removeError(group);
            return true;
        };

        this.showError = function(group, message) {
            this.removeError(group);
            const msg = document.createElement('span');
            msg.className = 'error-message';
            msg.style.color = "#d93025";
            msg.style.fontSize = "12px";
            msg.style.display = "block";
            msg.style.marginTop = "5px";
            msg.textContent = message;
            group.appendChild(msg);
            const input = group.querySelector('input');
            if(input) input.style.borderColor = "#d93025";
        };

        this.removeError = function(group) {
            const existing = group.querySelector('.error-message');
            if (existing) existing.remove();
            const input = group.querySelector('input');
            if(input) input.style.borderColor = "";
        };
    }

    const validator = new ValidatorForm();

    function showStep(index) {
    steps.forEach((step, i) => {
        step.style.setProperty('display', (i === index) ? 'block' : 'none', 'important');
        step.classList.toggle('active', i === index);
    });

    const currentStepEl = steps[index];

    const indicador = currentStepEl.querySelector('.step-indicator-container');
    const contadorTexto = currentStepEl.querySelector('.step-counter-text');

    if (index > 0) {
        if (indicador) {
            indicador.classList.add('is-visible');
            indicador.style.display = 'block'; // Garantia extra
        }

        const passoAtualVisivel = index; 
        const totalPerguntas = steps.length - 1;

        if (contadorTexto) {
            contadorTexto.textContent = `Passo ${passoAtualVisivel} de ${totalPerguntas}`;
        }
    }

    const formElement = document.getElementById('formProstata');
}

    if (inputData) {
        inputData.addEventListener('input', (e) => {
            e.target.value = validator.maskDate(e.target.value);
        });
    }

    document.querySelectorAll('.next-step').forEach(btn => {
        btn.addEventListener('click', function (event) {
            const currentStepEl = this.closest('.wizard-step');
            let isValid = true;

            currentStepEl.querySelectorAll('input[required]').forEach(input => {
                if (input.id === 'carteirinha') {
                    if (!validator.validateCarteirinha(input)) isValid = false;
                } else {
                    if (!validator.validateRequired(input)) isValid = false;
                }
            });

            const radioGroups = new Set();
            currentStepEl.querySelectorAll('input[type="radio"]').forEach(radio => radioGroups.add(radio.name));
            radioGroups.forEach(groupName => {
                if (!validator.validateRadio(groupName, currentStepEl)) isValid = false;
            });

              if (!validator.validateRecaptcha(currentStepEl)) {
                 isValid = false;
              }

            if (isValid) {
                if (currentStep < steps.length - 1) {
                    currentStep++;
                    showStep(currentStep);
                }
            }
        });
    });

    document.querySelectorAll('.prev-step').forEach(btn => {
        btn.addEventListener('click', () => {
            if (currentStep > 0) {
                currentStep--;
                showStep(currentStep);
            }
        });
    });

    	document.querySelectorAll('input[name="bloqueioHormonal"]').forEach(radio => {
		 radio.addEventListener('change', function() {
			const container = document.getElementById('container-medicamentos');
			const inputMedicamento = document.getElementById('quaisMedicamentos');

			if (this.value === 'Sim') {
				container.classList.add('show-container');
				inputMedicamento.setAttribute('required', 'true');
			} else {
				container.classList.remove('show-container');
				inputMedicamento.value = '';
				inputMedicamento.removeAttribute('required');
				const group = container.closest('.form-group') || container;
				const existingError = group.querySelector('.error-message');
				if (existingError) existingError.remove();
			}
		});
	});

       document.querySelectorAll('input[name="quimioveia"]').forEach(radio => {
    radio.addEventListener('change', function() {
        const container = document.getElementById('container-quimio');

        if (this.value === 'Sim') {
            container.classList.add('show-container');
            container.querySelectorAll('input[name="medicacao"]').forEach(r => r.required = true);
        } else {
            container.classList.remove('show-container');

            container.querySelectorAll('input[name="medicacao"]').forEach(r => {
                r.checked = false;
                r.required = false;
            });

            const existingError = container.querySelector('.error-message');
            if (existingError) existingError.remove();
        }
    });
});


    if (form) {
        form.addEventListener('submit', function (event) {
            event.preventDefault();

            const activeStep = document.querySelector('.wizard-step.active');
            let isValid = true;

            activeStep.querySelectorAll('input[required]').forEach(input => {
                if (!validator.validateRequired(input)) isValid = false;
            });

            const radioGroups = new Set();
            activeStep.querySelectorAll('input[type="radio"]').forEach(radio => radioGroups.add(radio.name));
            radioGroups.forEach(groupName => {
                if (!validator.validateRadio(groupName, activeStep)) isValid = false;
            });

            if (isValid) {
                enviarEmail();
            }
        });
    }

    	function enviarEmail() {
		$(".form-container-cancerProstata #submitBtn").prop('disabled', true).text('Enviando...');
		$("#loadingDiv").show();

		const preFixoAssuntoEmail = "Cancer de Próstata";
		const nome = $("#nome").val();
		const dataNascimento = $("#dataNascimento").val();
		const carteirinha = $("#carteirinha").val();
		const diagnostico = $("input[name='diagnostico']:checked").val();
		const psa = $("input[name='psa']:checked").val();
		const tratamentoHormonal = $("input[name='hormonal']:checked").val();
		const bloqueioHormonal = $("input[name='bloqueioHormonal']:checked").val();
        const medicamentos = $("#quaisMedicamentos").val();

        let bloqueioHormonalResp = bloqueioHormonal;
        if (bloqueioHormonal === "Sim" && medicamentos) {
            bloqueioHormonalResp += ` (Medicamentos: ${medicamentos})`;
        }

        const cancerProgressao = $("input[name='progressao']:checked").val();
        const metastases = $("input[name='metastase']:checked").val();
        const quimioVeia = $("input[name='quimioveia']:checked").val();
        const medicacaoSelecionada = document.querySelector("input[name='medicacao']:checked")?.value || "";

         let quimioVeiaResp = quimioVeia;
        if (quimioVeia === "Sim" && medicacaoSelecionada) {
            quimioVeiaResp += ` (Medicamento: ${medicacaoSelecionada})`;
        }
        const quimio = $("input[name='quimio']:checked").val();
        const remedio = $("input[name='remedio']:checked").val();
        const idade = $("input[name='faixa_etaria']:checked").val();
        const consulta = $("input[name='consultas']:checked").val();

		const subject = `${preFixoAssuntoEmail}`;
		const template = `

    <body>
    <div>
        <p>Segue os dados do cadastro:</p>

        <div>
            <div><strong>Nome:</strong> ${nome}</div>
            <div><strong>Data de Nascimento:</strong> ${dataNascimento}</div>
            <div><strong>Carteirinha:</strong> ${carteirinha}</div>
            <div><strong>1. Você possui diagnóstico confirmado de câncer de próstata?:</strong> ${diagnostico}</div>
            <div><strong>2. Seu PSA aumentou recentemente?:</strong> ${psa}</div>
            <div><strong>3. Você está em tratamento hormonal atualmente?:</strong> ${tratamentoHormonal}</div>
            <div><strong>4. Você faz ou já fez uso de bloqueio hormonal? (Injeção ou comprimido para controlar hormônio
				masculino. Exemplos: Zoladex, Lupron, Eligard, Firmagon, Orgovyx, Casodex, Flutamida, Nilandron, Xtandi
				(enzalutamida), Erleada (apalutamida), Nubeqa (darolutamida).):</strong> ${bloqueioHormonalResp}</div>
            <div><strong>5. Seu câncer está em progressão mesmo com o tratamento hormonal?:</strong> ${cancerProgressao}</div>
            <div><strong>6. Você possui metástases?:</strong> ${metastases}</div>
            <div><strong>7. Você faz quimioterapia na veia atualmente?:</strong> ${quimioVeiaResp}</div>
            <div><strong>8. Já fez quimioterapia anteriormente?:</strong> ${quimio}</div>
            <div><strong>9. Já usou Enzalutamida ou Abiraterona?:</strong> ${remedio}</div>
            <div><strong>10. Qual a sua idade?:</strong> ${idade}</div>
            <div><strong>11. Você tem disponibilidade para realizar consultas e exames presenciais no centro de pesquisa?:</strong> ${consulta}</div>
        </div>
    </div>
    </body>
    `;

		const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

		const data = {
			internalEmail: configuration.emailTo,
			subject: subject,
			nome: $("#nome").val(),
			template: cleanTemplate
		};

		const apiURL = window.location.origin + "/api/servicos/generico/enviar-email-dinamico";

		console.log("Subject gerado:", subject);
		console.log("Dados enviados para API:", JSON.stringify(data, null, 2));

		$.ajax({
			url: apiURL,
			method: "POST",
			headers: {
				'Accept': 'application/json',
				'Content-Type': 'application/json'
			},
			data: JSON.stringify(data),
			success: function (res, textStatus, jqXHR) {
				$("#loadingDiv").hide();
				if (jqXHR.status === 200) {
					showSuccessMessage();
				} else {
					showErrorMessage("Erro ao enviar os dados.");
					resetSubmitButton();
				}
			},
			error: function (err) {
				console.error("Erro na requisição:", err);
				$("#loadingDiv").hide();

				var errorMessage = "Erro técnico ao enviar os dados.";
				if (err.status === 400) errorMessage = "Dados inválidos. Verifique os campos preenchidos.";
				else if (err.status === 401) errorMessage = "Sessão expirada. Recarregue a página e tente novamente.";
				else if (err.status === 500) errorMessage = "Erro interno do servidor. Tente novamente em alguns minutos.";

				showErrorMessage(errorMessage);
				resetSubmitButton();
			}
		});
	}

	function showErrorMessage(message) {
    alert(message);
}

    function showSuccessMessage() {
        $(".form-container-cancerProstata #formCancer").hide();
        $(".form-container-cancerProstata #msgSucesso").css('display', 'flex').hide().fadeIn();
        //window.scrollTo(0, 0);
    }

    function resetSubmitButton() {
        $(".form-container-cancerProstata #submitBtn").prop('disabled', false).text('Enviar Cadastro');
    }
    showStep(currentStep);

})();
;

